1	import { z } from "zod";
2	import { dayRange } from "@/lib/finance/net-worth";
3	import { calendarDate } from "@/lib/finance/calendar";
4	import { decimalRatio, holdingValue } from "@/lib/finance/wealth";
5	import type { ScalableMcp } from "./client";
6	import { toMinor } from "./live";
7	import { decimalText } from "./portfolio";
8	
9	const CURRENCY = "EUR";
10	const PAGE_SIZE = 100, MAX_PAGES = 1000;
11	const TIMEFRAMES = ["max", "one_year", "six_months", "year_to_date"];
12	
13	type Chart = { currency: string; points: { at: string; price: string }[] };
14	export type HistoryRow = { id: string; at: string; currency?: string } & (
15	  | { kind: "security"; isin: string; side: string; quantity: string | null; amountText: string; price?: string | null }
16	  | { kind: "cash"; quantity?: undefined; amountText: string }
17	  | { kind: "crypto"; isin: string; side: string; quantity: string | null; amountText: string; price?: string | null });
18	export type HistoryInput = {
19	  rows: HistoryRow[]; charts: Record<string, Chart>;
20	  holdings: { isin: string; filled: number | string; currency?: string }[];
21	  cashBalance: number | string; timeZone: string;
22	  before: string;
23	};
24	export type HistoryDay = { date: string; securitiesMinor: bigint; cryptoMinor: bigint; cashMinor: bigint; totalMinor: bigint };
25	export type HistoryResult = { ok: true; days: HistoryDay[] } | { ok: false; reason: string };
26	
27	const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
28	const text = (value: number | string) => typeof value === "number" ? decimalText(value) : value;
29	const nextCursor = z.object({ nextCursor: z.string().nullish() });
30	const transactionsSchema = z.object({
31	  page: nextCursor.optional(),
32	  transactions: z.array(z.object({ id: z.string(), status: z.string(), currency: z.string().nullish(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
33	    security: z.object({ isin: z.string(), side: z.string().nullish(), quantity: decimal.nullish(), amount: decimal.nullish() }).nullish(),
34	    cash: z.object({ amount: decimal.nullish() }).nullish() })).default([]),
35	  crypto: z.object({ page: nextCursor.optional(), transactions: z.array(z.object({ id: z.string(), status: z.string(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
36	    side: z.string().nullish(), quantity: decimal.nullish(), amount: decimal.nullish() })).default([]) }).nullish(),
37	});
38	const holdingsSchema = z.object({
39	  holdings: z.array(z.object({ isin: z.string(), position: z.object({ filled: decimal }), currentQuote: z.object({ currency: z.string() }) })).default([]),
40	  cryptoHoldings: z.array(z.object({ ticker: z.string(), position: z.object({ filled: decimal }).nullish(), etpPositions: z.array(z.object({ isin: z.string(), position: z.object({ filled: decimal }).nullish() })).nullish() })).default([]),
41	});
42	const chartSchema = z.object({ currency: z.string().nullish(), dataPoints: z.array(z.object({ midPrice: decimal.nullish(), timestampUtc: z.string() })).default([]) });
43	const detailsSchema = z.object({ transaction: z.object({ security: z.object({ isin: z.string() }), securityTrade: z.object({ averagePrice: decimal.nullish() }).nullish() }) });
44	export type TradeDetail = { isin: string; price: string | null };
45	export type TradeDetails = { known: Map<string, TradeDetail>; remember: (id: string, detail: TradeDetail) => Promise<void> };
46	const settled = (row: { status: string; isCancellation?: boolean | null }) => row.status === "SETTLED" && !row.isCancellation;
47	
48	async function readRows(mcp: Pick<ScalableMcp, "callTool">, details: TradeDetails) {
49	  const securities = new Map<string, HistoryRow>(), crypto = new Map<string, Omit<Extract<HistoryRow, { kind: "crypto" }>, "isin">>();
50	  let cursor: string | undefined, cryptoCursor: string | undefined, securitiesDone = false, cryptoDone = false;
51	  for (let page = 0; !securitiesDone || !cryptoDone; page++) {
52	    if (page === MAX_PAGES) throw new Error("Scalable transactions never finished paging");
53	    const reply = transactionsSchema.parse(await mcp.callTool("list_portfolio_transactions", { pageSize: PAGE_SIZE, ...(cursor ? { cursor } : {}), ...(cryptoCursor ? { cryptoCursor } : {}) }));
54	    if (!securitiesDone) for (const row of reply.transactions.filter(settled)) {
55	      const base = { id: row.id, at: row.lastEventAt, ...(row.currency ? { currency: row.currency } : {}) };
56	      if (row.security) securities.set(row.id, { ...base, kind: "security", isin: row.security.isin, side: row.security.side ?? "unknown", quantity: row.security.quantity == null ? null : text(row.security.quantity), amountText: String(row.security.amount ?? 0) });
57	      else if (row.cash) securities.set(row.id, { ...base, kind: "cash", amountText: String(row.cash.amount ?? 0) });
58	    }
59	    if (!cryptoDone) for (const row of (reply.crypto?.transactions ?? []).filter(settled))
60	      crypto.set(row.id, { id: row.id, at: row.lastEventAt, kind: "crypto", side: row.side ?? "unknown", quantity: row.quantity == null ? null : text(row.quantity), amountText: String(row.amount ?? 0) });
61	    cursor = securitiesDone ? undefined : reply.page?.nextCursor || undefined;
62	    cryptoCursor = cryptoDone ? undefined : reply.crypto?.page?.nextCursor || undefined;
63	    securitiesDone = !cursor; cryptoDone = !cryptoCursor;
64	  }
65	  const detail = async (id: string) => {
66	    const saved = details.known.get(id);
67	    if (saved) return saved;
68	    const { security, securityTrade } = detailsSchema.parse(await mcp.callTool("get_transaction_details", { transactionId: id })).transaction;
69	    const price = securityTrade?.averagePrice != null && Number(securityTrade.averagePrice) > 0 ? text(securityTrade.averagePrice) : null;
70	    const found = { isin: security.isin, price };
71	    await details.remember(id, found);
72	    return found;
73	  };
74	  const rows: HistoryRow[] = [];
75	  for (const row of securities.values()) rows.push(row.kind === "security" ? { ...row, price: (await detail(row.id)).price } : row);
76	  for (const row of crypto.values()) { const { isin, price } = await detail(row.id); rows.push({ ...row, isin, price }); }
77	  return rows;
78	}
79	
80	async function readChart(mcp: Pick<ScalableMcp, "callTool">, isin: string): Promise<Chart> {
81	  const replies: z.infer<typeof chartSchema>[] = [];
82	  for (const timeframe of TIMEFRAMES) replies.push(chartSchema.parse(await mcp.callTool("get_security_chart", { isin, timeframe })));
83	  const points = new Map(replies.flatMap(reply => reply.dataPoints.flatMap(point => point.midPrice != null && Number(point.midPrice) > 0 ? [[point.timestampUtc, text(point.midPrice)] as const] : [])));
84	  return { currency: replies.find(reply => reply.dataPoints.length && reply.currency !== CURRENCY)?.currency ?? CURRENCY, points: [...points].map(([at, price]) => ({ at, price })) };
85	}
86	
87	export async function readHistoryInput(mcp: Pick<ScalableMcp, "callTool">, timeZone: string, before: string, details: TradeDetails): Promise<HistoryInput> {
88	  const rows = await readRows(mcp, details);
89	  const holdings = holdingsSchema.parse(await mcp.callTool("get_portfolio_holdings"));
90	  const cash = z.object({ cash: z.object({ cashBalance: decimal }) }).parse(await mcp.callTool("get_portfolio_cash_breakdown"));
91	  const unbacked = holdings.cryptoHoldings.find(coin => Number(coin.position?.filled ?? 0) > 0 && !coin.etpPositions?.some(etp => Number(etp.position?.filled ?? 0) > 0));
92	  if (unbacked) throw new Error(`${unbacked.ticker} is held without an ETP position`);
93	  const charts: Record<string, Chart> = {};
94	  for (const isin of new Set(rows.flatMap(row => row.kind === "cash" ? [] : [row.isin]))) charts[isin] = await readChart(mcp, isin);
95	  return { rows, charts, timeZone, before, cashBalance: cash.cash.cashBalance,
96	    holdings: [...holdings.holdings.map(holding => ({ isin: holding.isin, filled: holding.position.filled, currency: holding.currentQuote.currency })),
97	      ...holdings.cryptoHoldings.flatMap(coin => (coin.etpPositions ?? []).flatMap(etp => etp.position ? [{ isin: etp.isin, filled: etp.position.filled }] : []))] };
98	}
99	
100	const ONE = 10n ** 18n, TOLERANCE = 10n ** 12n, CASH_TOLERANCE = 100n;
101	const CENTS = 100n, CENT_SCALE = ONE / CENTS;
102	const scaled = (value: number | string) => { const ratio = decimalRatio(text(value)); return ratio.numerator * ONE / ratio.denominator; };
103	const decimalOf = (value: bigint) => `${value / ONE}.${(value % ONE).toString().padStart(18, "0")}`;
104	const value = (quantity: bigint, price: bigint) => holdingValue(decimalOf(quantity), decimalOf(price), CURRENCY);
105	const absolute = (minor: bigint) => minor < 0n ? -minor : minor;
106	const tradePrices = (rows: Exclude<HistoryRow, { kind: "cash" }>[]) => rows.flatMap(row => {
107	  if (row.price) return [{ at: row.at, price: scaled(row.price) }];
108	  const minor = BigInt(toMinor(row.amountText, CURRENCY)), quantity = scaled(row.quantity!);
109	  return minor !== 0n && quantity > 0n ? [{ at: row.at, price: absolute(minor) * CENT_SCALE * ONE / quantity }] : [];
110	});
111	
112	type Prices = { points: { day: string; at: number; price: bigint }[]; next: number; current: bigint | null };
113	function pricesFrom(chart: Chart | undefined, timeZone: string, trades: { at: string; price: bigint }[] = []): Prices {
114	  const points = [...(chart?.points ?? []).map(point => ({ at: point.at, price: scaled(point.price) })), ...trades]
115	    .map(point => ({ day: calendarDate(point.at, timeZone), at: Date.parse(point.at), price: point.price })).sort((a, b) => a.at - b.at);
116	  return { points, next: 0, current: null };
117	}
118	function priceOn(prices: Prices, date: string) {
119	  while (prices.next < prices.points.length && prices.points[prices.next].day <= date) prices.current = prices.points[prices.next++].price;
120	  return prices.current;
121	}
122	
123	function replay(input: HistoryInput): HistoryResult {
124	  const fail = (reason: string): HistoryResult => ({ ok: false, reason });
125	  const rows = [...input.rows].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
126	  if (!rows.length) return fail("Scalable returned no settled transactions");
127	
128	  for (const row of rows) {
129	    if (row.currency && row.currency !== CURRENCY) return fail(`A transaction is in ${row.currency}, and only ${CURRENCY} is supported`);
130	    if (row.kind === "cash") continue;
131	    if (row.side !== "BUY" && row.side !== "SELL") return fail(`Transaction ${row.id} has an unknown side: ${row.side}`);
132	    if (row.quantity === null) return fail(`Transaction ${row.id} has no quantity`);
133	  }
134	  for (const [isin, chart] of Object.entries(input.charts)) if (chart.currency !== CURRENCY) return fail(`${isin} is priced in ${chart.currency}, and only ${CURRENCY} is supported`);
135	  for (const holding of input.holdings) if (holding.currency && holding.currency !== CURRENCY && Number(holding.filled) > 0) return fail(`${holding.isin} is priced in ${holding.currency}, and only ${CURRENCY} is supported`);
136	
137	  const trades = rows.filter(row => row.kind !== "cash");
138	  const cryptoIsins = new Set(trades.filter(row => row.kind === "crypto").map(row => row.isin));
139	  const shares = new Map<string, bigint>(), prices = new Map<string, Prices>();
140	  for (const isin of new Set(trades.map(row => row.isin))) {
141	    shares.set(isin, 0n);
142	    prices.set(isin, pricesFrom(input.charts[isin], input.timeZone, tradePrices(trades.filter(row => row.isin === isin))));
143	  }
144	
145	  const byDay = new Map<string, HistoryRow[]>();
146	  for (const row of rows) {
147	    const day = calendarDate(row.at, input.timeZone);
148	    byDay.set(day, [...(byDay.get(day) ?? []), row]);
149	  }
150	  const eventDays = [...byDay.keys()].sort(), first = eventDays[0], lastEvent = eventDays.at(-1)!;
151	  const dayBefore = new Date(Date.parse(`${input.before}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
152	
153	  const days: HistoryDay[] = [];
154	  let cashMinor = 0n;
155	  for (const date of dayRange(first, lastEvent > dayBefore ? lastEvent : dayBefore)) {
156	    for (const row of byDay.get(date) ?? []) {
157	      const amount = BigInt(toMinor(row.amountText, CURRENCY));
158	      cashMinor += amount;
159	      if (row.kind === "cash") continue;
160	      const quantity = scaled(row.quantity!);
161	      shares.set(row.isin, shares.get(row.isin)! + (row.side === "BUY" ? quantity : -quantity));
162	    }
163	    for (const [isin, held] of shares) if (held < -TOLERANCE) return fail(`Shares of ${isin} go negative on ${date}`);
164	    if (date > dayBefore) continue;
165	
166	    let securitiesMinor = 0n, cryptoMinor = 0n;
167	    for (const [isin, held] of shares) {
168	      if (held <= TOLERANCE) continue;
169	      const price = priceOn(prices.get(isin)!, date);
170	      if (price === null) return fail(`${isin} has no price on ${date}`);
171	      if (cryptoIsins.has(isin)) cryptoMinor += value(held, price);
172	      else securitiesMinor += value(held, price);
173	    }
174	    days.push({ date, securitiesMinor, cryptoMinor, cashMinor, totalMinor: securitiesMinor + cryptoMinor + cashMinor });
175	  }
176	
177	  for (const isin of new Set([...shares.keys(), ...input.holdings.map(holding => holding.isin)])) {
178	    const held = input.holdings.find(holding => holding.isin === isin)?.filled ?? 0, replayed = shares.get(isin) ?? 0n;
179	    if (absolute(replayed - scaled(held)) > TOLERANCE) return fail(`Shares of ${isin} replay to ${decimalOf(replayed)}, but Scalable holds ${text(held)}`);
180	  }
181	  const balance = BigInt(toMinor(input.cashBalance, CURRENCY));
182	  if (absolute(cashMinor - balance) > CASH_TOLERANCE) return fail(`Cash replays to ${cashMinor} cents, but Scalable holds ${balance}`);
183	  return { ok: true, days: days.filter(day => day.date < input.before) };
184	}
185	
186	export function calculateHistory(input: HistoryInput): HistoryResult {
187	  try { return replay(input); } catch (error) { return { ok: false, reason: error instanceof Error ? error.message : "The transactions could not be read" }; }
188	}
